{
  "party": "Parcelly",
  "role": "provider",
  "goal": "Enable partner shops to create and track parcel and pallet shipments across the UK, receive automated status updates via webhooks, and make idempotent API calls safely.",
  "data_we_have": [
    {
      "concept": "Partner identifier",
      "representation": "string",
      "examples": ["prt_1", "prt_alpha"]
    },
    {
      "concept": "Partner API key",
      "representation": "string (Bearer token format pk_test_<hex32>)",
      "examples": ["pk_test_abc123def456abc123def456abc123def4", "pk_test_11111111111111111111111111111111"]
    },
    {
      "concept": "Shipment ID",
      "representation": "string",
      "examples": ["shp_1", "shp_xyz"]
    },
    {
      "concept": "Service type",
      "representation": "string ('parcel' or 'pallet')",
      "examples": ["parcel", "pallet"]
    },
    {
      "concept": "Partner order reference",
      "representation": "string",
      "examples": ["ORD-1001", "ORDER2025-001"]
    },
    {
      "concept": "Shipment status",
      "representation": "string",
      "examples": ["CREATED", "IN_TRANSIT", "DELIVERED", "FAILED"]
    },
    {
      "concept": "Tracking number",
      "representation": "string (format PCL<n>GB for parcels, PAL<n>GB for pallets)",
      "examples": ["PCL1GB", "PAL5GB"]
    },
    {
      "concept": "Price in pence",
      "representation": "integer",
      "examples": ["1299", "1599", "1999", "8900"]
    },
    {
      "concept": "Receiver name",
      "representation": "string",
      "examples": ["John Smith", "Jane Doe"]
    },
    {
      "concept": "Receiver phone number",
      "representation": "string (UK mobile E.164, +447XXXXXXXXX)",
      "examples": ["+447700900200", "+447700900300", "+447700900201"]
    },
    {
      "concept": "Receiver address street",
      "representation": "string",
      "examples": ["Long Street", "High Road"]
    },
    {
      "concept": "Receiver address building",
      "representation": "string",
      "examples": ["5", "Flat 12"]
    },
    {
      "concept": "Receiver address flat",
      "representation": "string",
      "examples": ["3", ""]
    },
    {
      "concept": "Receiver address postcode",
      "representation": "string (uppercase, one space, format ^[A-Z]{1,2}\\d[A-Z\\d]? \\d[A-Z]{2}$)",
      "examples": ["E1 6AN", "SW1A 1AA", "M1 1AB"]
    },
    {
      "concept": "Receiver address city",
      "representation": "string",
      "examples": ["London", "Manchester", "Birmingham"]
    },
    {
      "concept": "Receiver address country",
      "representation": "string (fixed 'GB')",
      "examples": ["GB"]
    },
    {
      "concept": "Parcel weight (grams)",
      "representation": "integer",
      "examples": ["14500", "4000", "20000"]
    },
    {
      "concept": "Parcel size",
      "representation": "string ('A', 'B', or 'C')",
      "examples": ["A", "B", "C"]
    },
    {
      "concept": "Pallet weight (grams)",
      "representation": "integer",
      "examples": ["27000", "50000", "900000"]
    },
    {
      "concept": "Pallet type",
      "representation": "string (currently 'EUR')",
      "examples": ["EUR"]
    },
    {
      "concept": "Creation timestamp",
      "representation": "string (ISO 8601 date-time)",
      "examples": ["2026-10-06T10:00:00.000Z", "2026-11-01T14:30:00.000Z"]
    },
    {
      "concept": "Last update timestamp",
      "representation": "string (ISO 8601 date-time)",
      "examples": ["2026-10-06T10:00:00.000Z", "2026-10-06T12:00:00.000Z"]
    },
    {
      "concept": "Webhook event type",
      "representation": "string (only 'shipment.status_changed')",
      "examples": ["shipment.status_changed"]
    },
    {
      "concept": "Webhook event occurred at",
      "representation": "string (ISO 8601 date-time)",
      "examples": ["2026-10-06T12:00:00.000Z"]
    },
    {
      "concept": "Idempotency key",
      "representation": "string (partner‑scoped, blank treated as missing, max 255 chars)",
      "examples": ["ORD-1001", "ABC-999", ""]
    }
  ],
  "capabilities_offered": [
    "Create a parcel shipment (POST /v1/shipments)",
    "Create a pallet shipment (POST /v1/pallets)",
    "Retrieve shipment details (GET /v1/shipments/{id})",
    "Retrieve pallet details (GET /v1/pallets/{id})",
    "Subscribe to webhook events (POST /v1/webhooks)",
    "Generate idempotent request IDs (partner‑scoped key)"
  ],
  "constraints": [
    "Only shipments with status CREATED, IN_TRANSIT, DELIVERED, or FAILED are valid",
    "Service type must be either 'parcel' or 'pallet'",
    "Price must be a non‑negative integer in pence",
    "Weight fields must be positive integers",
    "Postcode must match the regex ^[A-Z]{1,2}\\d[A-Z\\d]? \\d[A-Z]{2}$",
    "Country must be exactly 'GB'",
    "Idempotency key must be a string of up to 255 characters; blank values are treated as missing"
  ],
  "edge_cases": [
    "Partner sends an invalid API key – authentication fails",
    "Service type is omitted or set to an unsupported value",
    "Price is negative or exceeds 9999 pence",
    "Weight is zero or missing",
    "Postcode does not match the required pattern",
    "Country is not 'GB'",
    "Idempotency key exceeds 255 characters",
    "Webhook payload contains an unrecognized event type"
  ],
  "open_needs": [
    "Support for international shipments outside the UK",
    "Additional service types such as 'letter' or 'express'",
    "Real‑time tracking status updates beyond status_changed",
    "Bulk creation endpoint for multiple shipments",
    "Enhanced error codes for partner debugging"
  ]
}

