{
  "message": "Starting the Parcelly provider integration. I'll draft the contract with schemas, operations, webhooks, secrets, and provider scenarios based on the internal system model. This covers parcel/pallet creation, webhook delivery with HMAC signatures, idempotency, weight/size/postcode validation, and sandbox test endpoints.",
  "patches": [
    {
      "op": "add",
      "path": "/secrets/-",
      "value": {
        "name": "partner_api_key",
        "description": "Bearer token for Authorization header (pk_test_<hex32>)"
      }
    },
    {
      "op": "add",
      "path": "/secrets/-",
      "value": {
        "name": "webhook_secret",
        "description": "HMAC-SHA256 secret for signing webhook payloads"
      }
    },
    {
      "op": "add",
      "path": "/glossary/parcel",
      "value": "A single parcel shipment up to 25 kg"
    },
    {
      "op": "add",
      "path": "/glossary/pallet",
      "value": "A pallet shipment from 25.001 kg to 1 000 kg"
    },
    {
      "op": "add",
      "path": "/glossary/reference",
      "value": "Partner's order reference, used for idempotency and lookup"
    },
    {
      "op": "add",
      "path": "/glossary/size",
      "value": "Parcel size tier: A (<=5 kg), B (5.01-15 kg), C (15.01-25 kg)"
    },
    {
      "op": "add",
      "path": "/schemas/CreateShipmentRequest",
      "value": {
        "type": "object",
        "required": ["reference", "receiver", "parcel"],
        "additionalProperties": false,
        "properties": {
          "reference": { "type": "string", "minLength": 1 },
          "receiver": {
            "type": "object",
            "required": ["name", "phone", "address"],
            "additionalProperties": false,
            "properties": {
              "name": { "type": "string", "minLength": 1 },
              "phone": { "type": "string", "pattern": "^\\+447\\d{9}$" },
              "address": {
                "type": "object",
                "required": ["street", "postcode", "city", "country"],
                "additionalProperties": false,
                "properties": {
                  "street": { "type": "string", "minLength": 1 },
                  "building": { "type": "string" },
                  "flat": { "type": "string" },
                  "postcode": { "type": "string", "pattern": "^[A-Z]{1,2}\\d[A-Z\\d]? \\d[A-Z]{2}$" },
                  "city": { "type": "string", "minLength": 1 },
                  "country": { "type": "string", "enum": ["GB"] }
                }
              }
            }
          },
          "parcel": {
            "type": "object",
            "required": ["weight_g", "size"],
            "additionalProperties": false,
            "properties": {
              "weight_g": { "type": "integer", "minimum": 1, "maximum": 25000 },
              "size": { "type": "string", "enum": ["A", "B", "C"] }
            }
          }
        }
      }
    },
    {
      "op": "add",
      "path": "/schemas/CreatePalletRequest",
      "value": {
        "type": "object",
        "required": ["reference", "receiver", "pallet"],
        "additionalProperties": false,
        "properties": {
          "reference": { "type": "string", "minLength": 1 },
          "receiver": {
            "type": "object",
            "required": ["name", "phone", "address"],
            "additionalProperties": false,
            "properties": {
              "name": { "type": "string", "minLength": 1 },
              "phone": { "type": "string", "pattern": "^\\+447\\d{9}$" },
              "address": {
                "type": "object",
                "required": ["street", "postcode", "city", "country"],
                "additionalProperties": false,
                "properties": {
                  "street": { "type": "string", "minLength": 1 },
                  "building": { "type": "string" },
                  "flat": { "type": "string" },
                  "postcode": { "type": "string", "pattern": "^[A-Z]{1,2}\\d[A-Z\\d]? \\d[A-Z]{2}$" },
                  "city": { "type": "string", "minLength": 1 },
                  "country": { "type": "string", "enum": ["GB"] }
                }
              }
            }
          },
          "pallet": {
            "type": "object",
            "required": ["weight_g", "pallet_type"],
            "additionalProperties": false,
            "properties": {
              "weight_g": { "type": "integer", "minimum": 25001, "maximum": 1000000 },
              "pallet_type": { "type": "string", "enum": ["EUR"] }
            }
          }
        }
      }
    },
    {
      "op": "add",
      "path": "/schemas/Shipment",
      "value": {
        "type": "object",
        "required": ["id", "service", "reference", "status", "tracking_number", "price_pence", "receiver", "created_at", "updated_at"],
        "additionalProperties": false,
        "properties": {
          "id": { "type": "string", "pattern": "^shp_\\d+$" },
          "service": { "type": "string", "enum": ["parcel", "pallet"] },
          "reference": { "type": "string" },
          "status": { "type": "string", "enum": ["CREATED", "COLLECTED", "IN_TRANSIT", "OUT_FOR_DELIVERY", "DELIVERED", "FAILED"] },
          "tracking_number": { "type": "string", "pattern": "^(PCL|PAL)\\d+GB$" },
          "price_pence": { "type": "integer", "minimum": 0 },
          "receiver": {
            "type": "object",
            "required": ["name", "phone", "address"],
            "properties": {
              "name": { "type": "string" },
              "phone": { "type": "string" },
              "address": {
                "type": "object",
                "required": ["street", "postcode", "city", "country"],
                "properties": {
                  "street": { "type": "string" },
                  "building": { "type": "string" },
                  "flat": { "type": "string" },
                  "postcode": { "type": "string" },
                  "city": { "type": "string" },
                  "country": { "type": "string" }
                }
              }
            }
          },
          "parcel": {
            "type": "object",
            "properties": {
              "weight_g": { "type": "integer" },
              "size": { "type": "string", "enum": ["A", "B", "C"] }
            }
          },
          "pallet": {
            "type": "object",
            "properties": {
              "weight_g": { "type": "integer" },
              "pallet_type": { "type": "string", "enum": ["EUR"] }
            }
          },
          "created_at": { "type": "string", "format": "date-time" },
          "updated_at": { "type": "string", "format": "date-time" }
        }
      }
    },
    {
      "op": "add",
      "path": "/schemas/Error",
      "value": {
        "type": "object",
        "required": ["code", "message"],
        "additionalProperties": false,
        "properties": {
          "code": { "type": "string" },
          "message": { "type": "string" }
        }
      }
    },
    {
      "op": "add",
      "path": "/schemas/ShipmentStatusChanged",
      "value": {
        "type": "object",
        "required": ["event", "shipment_id", "reference", "status", "occurred_at"],
        "additionalProperties": false,
        "properties": {
          "event": { "type": "string", "const": "shipment.status_changed" },
          "shipment_id": { "type": "string" },
          "reference": { "type": "string" },
          "status": { "type": "string" },
          "occurred_at": { "type": "string", "format": "date-time" }
        }
      }
    },
    {
      "op": "add",
      "path": "/schemas/WebhookRegistrationRequest",
      "value": {
        "type": "object",
        "required": ["url", "secret"],
        "additionalProperties": false,
        "properties": {
          "url": { "type": "string", "format": "uri" },
          "secret": { "type": "string", "minLength": 1 }
        }
      }
    },
    {
      "op": "add",
      "path": "/schemas/WebhookRegistrationResponse",
      "value": {
        "type": "object",
        "required": ["url"],
        "additionalProperties": false,
        "properties": {
          "url": { "type": "string" }
        }
      }
    },
    {
      "op": "add",
      "path": "/operations/create_shipment",
      "value": {
        "description": "Create a new parcel shipment (up to 25 kg)",
        "direction": "consumer_to_provider",
        "request": {
          "method": "POST",
          "path": "/v1/shipments",
          "headers": {
            "Authorization": { "required": true, "pattern": "^Bearer pk_test_[0-9a-f]{32}$" },
            "Idempotency-Key": { "required": false, "pattern": "^.{1,255}$" }
          },
          "body": { "$ref": "#/schemas/CreateShipmentRequest" }
        },
        "responses": {
          "201": { "body": { "$ref": "#/schemas/Shipment" } },
          "400": { "body": { "$ref": "#/schemas/Error" } },
          "401": { "body": { "$ref": "#/schemas/Error" } },
          "422": { "body": { "$ref": "#/schemas/Error" } }
        },
        "stub": {
          "default_status": 201,
          "body": {
            "id": "shp_{{seq}}",
            "service": "parcel",
            "reference": "{{request.body.reference}}",
            "status": "CREATED",
            "tracking_number": "PCL{{seq}}GB",
            "price_pence": 1599,
            "receiver": "{{request.body.receiver}}",
            "parcel": "{{request.body.parcel}}",
            "created_at": "{{now}}",
            "updated_at": "{{now}}"
          },
          "idempotent_on_header": "Idempotency-Key"
        }
      }
    },
    {
      "op": "add",
      "path": "/operations/create_pallet",
      "value": {
        "description": "Create a new pallet shipment (25.001 kg - 1 000 kg)",
        "direction": "consumer_to_provider",
        "request": {
          "method": "POST",
          "path": "/v1/pallets",
          "headers": {
            "Authorization": { "required": true, "pattern": "^Bearer pk_test_[0-9a-f]{32}$" },
            "Idempotency-Key": { "required": false, "pattern": "^.{1,255}$" }
          },
          "body": { "$ref": "#/schemas/CreatePalletRequest" }
        },
        "responses": {
          "201": { "body": { "$ref": "#/schemas/Shipment" } },
          "400": { "body": { "$ref": "#/schemas/Error" } },
          "401": { "body": { "$ref": "#/schemas/Error" } },
          "422": { "body": { "$ref": "#/schemas/Error" } }
        },
        "stub": {
          "default_status": 201,
          "body": {
            "id": "shp_{{seq}}",
            "service": "pallet",
            "reference": "{{request.body.reference}}",
            "status": "CREATED",
            "tracking_number": "PAL{{seq}}GB",
            "price_pence": 8900,
            "receiver": "{{request.body.receiver}}",
            "pallet": "{{request.body.pallet}}",
            "created_at": "{{now}}",
            "updated_at": "{{now}}"
          },
          "idempotent_on_header": "Idempotency-Key"
        }
      }
    },
    {
      "op": "add",
      "path": "/operations/get_shipment",
      "value": {
        "description": "Retrieve a specific shipment by ID (partner-scoped)",
        "direction": "consumer_to_provider",
        "request": {
          "method": "GET",
          "path": "/v1/shipments/{id}",
          "headers": {
            "Authorization": { "required": true, "pattern": "^Bearer pk_test_[0-9a-f]{32}$" }
          }
        },
        "responses": {
          "200": { "body": { "$ref": "#/schemas/Shipment" } },
          "401": { "body": { "$ref": "#/schemas/Error" } },
          "404": { "body": { "$ref": "#/schemas/Error" } }
        },
        "stub": {
          "default_status": 200,
          "body": {
            "id": "{{request.path.id}}",
            "service": "parcel",
            "reference": "ORD-1",
            "status": "CREATED",
            "tracking_number": "PCL1GB",
            "price_pence": 1599,
            "receiver": { "name": "John Smith", "phone": "+447700900200", "address": { "street": "Long Street", "building": "5", "flat": "3", "postcode": "E1 6AN", "city": "London", "country": "GB" } },
            "parcel": { "weight_g": 14500, "size": "B" },
            "created_at": "2026-10-06T10:00:00.000Z",
            "updated_at": "2026-10-06T10:00:00.000Z"
          }
        }
      }
    },
    {
      "op": "add",
      "path": "/operations/get_shipment_by_reference",
      "value": {
        "description": "Retrieve the most recent shipment for a reference",
        "direction": "consumer_to_provider",
        "request": {
          "method": "GET",
          "path": "/v1/shipments",
          "headers": {
            "Authorization": { "required": true, "pattern": "^Bearer pk_test_[0-9a-f]{32}$" }
          },
          "query": {
            "reference": { "required": true, "type": "string" }
          }
        },
        "responses": {
          "200": { "body": { "$ref": "#/schemas/Shipment" } },
          "400": { "body": { "$ref": "#/schemas/Error" } },
          "401": { "body": { "$ref": "#/schemas/Error" } },
          "404": { "body": { "$ref": "#/schemas/Error" } }
        },
        "stub": {
          "default_status": 200,
          "body": {
            "id": "shp_1",
            "service": "parcel",
            "reference": "{{request.query.reference}}",
            "status": "CREATED",
            "tracking_number": "PCL1GB",
            "price_pence": 1599,
